<?php require __DIR__ . '/_bootstrap.php'; $q=$db->prepare('SELECT d.idDepot,d.fichier,d.dateDepot,e.titre,u.prenom,u.nom FROM depot d INNER JOIN evaluation e ON e.idEvaluation=d.idEvaluation INNER JOIN module m ON m.idModule=e.idModule INNER JOIN etudiant et ON et.idUtilisateur=d.idEtudiant INNER JOIN utilisateur u ON u.idUtilisateur=et.idUtilisateur WHERE m.idFormateur=:id ORDER BY d.dateDepot DESC'); $q->execute(['id'=>$formateurId]); $depots=$q->fetchAll(); $pageTitle='Travaux à corriger'; $activeMenu='correction'; require __DIR__ . '/../../includes/header.php'; ?><div class="card"><h2>Travaux à corriger</h2><table class="director-table"><thead><tr><th>Évaluation</th><th>Étudiant</th><th>Fichier</th><th>Déposé le</th></tr></thead><tbody><?php foreach($depots as $depot): ?><tr><td><?=htmlspecialchars($depot['titre'])?></td><td><?=htmlspecialchars($depot['prenom'].' '.$depot['nom'])?></td><td><?=htmlspecialchars($depot['fichier'])?></td><td><?=htmlspecialchars($depot['dateDepot'])?></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__ . '/../../includes/footer.php'; ?>